class Solution {
public:
    bool isItPossible(std::string word1, std::string word2) {
        std::vector<int> c1(26, 0), c2(26, 0);
        for (char c : word1) c1[c - 'a']++;
        for (char c : word2) c2[c - 'a']++;

        for (int i = 0; i < 26; ++i) {
            if (c1[i] == 0) continue;
            for (int j = 0; j < 26; ++j) {
                if (c2[j] == 0) continue;
                c1[i]--; c1[j]++;
                c2[j]--; c2[i]++;

                int d1 = 0, d2 = 0;
                for (int k = 0; k < 26; ++k) {
                    if (c1[k] > 0) d1++;
                    if (c2[k] > 0) d2++;
                }
                if (d1 == d2) return true;

                c1[i]++; c1[j]--;
                c2[j]++; c2[i]--;
            }
        }
        return false;
    }
};

